    ctx.beginPath(); ctx.arc(-9, -1, 6.5, Math.PI * 0.85, Math.PI * 1.55); ctx.stroke();
    ctx.strokeStyle = C.sh("#8d9499", -45);
    ctx.beginPath(); ctx.arc(-9, -1, 4.8, 0.2, 2.4); ctx.stroke();
