    ctx.beginPath();
    ctx.moveTo(-4, 5); ctx.lineTo(4, 5); ctx.lineTo(2, 10); ctx.lineTo(-2, 10);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = C.dk; ctx.stroke();
    ctx.fillStyle = "#d8b44a";
