BLD_DETAIL["radar"] = {
  draw: function (ctx, C, t) {
    ctx.lineWidth = 1;
    // equipment shack
    ctx.fillStyle = "#5f6d66"; ctx.fillRect(-10, 3, 8, 6);
    ctx.fillStyle = C.sh("#5f6d66", 30); ctx.fillRect(-10, 3, 8, 1.5);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-10, 3, 8, 6);
    ctx.fillStyle = C.main; ctx.fillRect(-9, 5.5, 2.5, 2);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-9, 5.5, 2.5, 2);
    // pedestal
    ctx.fillStyle = "#84888c";
    ctx.beginPath(); ctx.arc(0, -1, 3.2, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = C.dk; ctx.stroke();
    ctx.strokeStyle = C.sh("#84888c", 40);
    ctx.beginPath(); ctx.arc(0, -1, 3.2, Math.PI * 0.9, Math.PI * 1.6); ctx.stroke();
    // sweeping dish
    var a = Math.sin(t * 0.8) * 1.1;
    ctx.save();
    ctx.translate(0, -1); ctx.rotate(a);
    ctx.fillStyle = "#aeb6bc";
    ctx.beginPath(); ctx.ellipse(0, -4, 5.5, 2.6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = C.dk; ctx.stroke();
    ctx.strokeStyle = C.sh("#aeb6bc", -40);
    ctx.beginPath(); ctx.ellipse(0, -3.5, 3.6, 1.5, 0, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, -4); ctx.lineTo(0, -7.6); ctx.stroke();
    ctx.fillStyle = C.dk;
    ctx.beginPath(); ctx.arc(0, -7.6, 0.8, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
    // blinking beacon
    var on = Math.sin(t * 5) > 0;
    if (on) {
      ctx.globalAlpha = 0.35; ctx.fillStyle = "#e04338";
      ctx.beginPath(); ctx.arc(6, 4, 2.4, 0, Math.PI * 2); ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.fillStyle = on ? "#e04338" : "#5a2a26";
    ctx.beginPath(); ctx.arc(6, 4, 1.2, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = C.dk; ctx.stroke();
  }
};

BLD_DETAIL["lab"] = {
  draw: function (ctx, C, t) {
    ctx.lineWidth = 1;
    var pulse = 0.5 + 0.5 * Math.sin(t * 2.2);
    // annex
    ctx.fillStyle = "#6d7378"; ctx.fillRect(3, 2, 7, 6);
    ctx.fillStyle = C.sh("#6d7378", 30); ctx.fillRect(3, 2, 7, 1.5);
    ctx.strokeStyle = C.dk; ctx.strokeRect(3, 2, 7, 6);
    ctx.fillStyle = C.main; ctx.fillRect(4, 4.5, 2.5, 2);
    ctx.strokeStyle = C.dk; ctx.strokeRect(4, 4.5, 2.5, 2);
    // pulsing violet glow
    ctx.globalAlpha = 0.22 + 0.28 * pulse;
    ctx.fillStyle = "#b06ae0";
    ctx.beginPath(); ctx.arc(-2, -1, 8, 0, Math.PI * 2); ctx.fill();
    ctx.globalAlpha = 1;
    // geodesic dome
    ctx.fillStyle = "#b9c0c6";
    ctx.beginPath(); ctx.arc(-2, -1, 6, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = C.dk; ctx.stroke();
    ctx.strokeStyle = C.sh("#b9c0c6", -35);
    ctx.beginPath(); ctx.arc(-2, 3.5, 7.2, -2.5, -0.64); ctx.stroke();
    ctx.beginPath(); ctx.arc(-2, -5.5, 7.2, 0.64, 2.5); ctx.stroke();
    ctx.beginPath(); ctx.arc(-2, -1, 2.2, 0, Math.PI * 2); ctx.stroke();
    ctx.strokeStyle = C.sh("#b9c0c6", 45);
    ctx.beginPath(); ctx.arc(-2, -1, 6, Math.PI * 0.9, Math.PI * 1.6); ctx.stroke();
    // glowing cap port
    ctx.fillStyle = "#b06ae0"; ctx.globalAlpha = 0.5 + 0.5 * pulse;
    ctx.beginPath(); ctx.arc(-2, -1, 1.4, 0, Math.PI * 2); ctx.fill();
    ctx.globalAlpha = 1;
    // antenna mast (tall)
    ctx.strokeStyle = C.dk;
    ctx.beginPath();
    ctx.moveTo(7, 0); ctx.lineTo(7, -8);
    ctx.moveTo(5.8, -6); ctx.lineTo(8.2, -6);
    ctx.moveTo(6.2, -4); ctx.lineTo(7.8, -4);
    ctx.stroke();
    ctx.fillStyle = "#e04338";
    ctx.beginPath(); ctx.arc(7, -8, 0.7, 0, Math.PI * 2); ctx.fill();
  }
};

BLD_DETAIL["depot"] = {
  draw: function (ctx, C, t) {
    ctx.lineWidth = 1;
    // service bay floor
    ctx.fillStyle = "#84888c"; ctx.fillRect(-13, -8, 22, 17);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-13, -8, 22, 17);
    // oil stains
    ctx.globalAlpha = 0.5; ctx.fillStyle = "#26292c";
    ctx.beginPath(); ctx.arc(-8, 5, 2.2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(6, -4, 1.6, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(1, 6.5, 1.2, 0, Math.PI * 2); ctx.fill();
    ctx.globalAlpha = 1;
    // vehicle pit
    ctx.fillStyle = "#2e3236"; ctx.fillRect(-4, -5, 8, 12);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-4, -5, 8, 12);
    ctx.strokeStyle = C.sh("#84888c", 45);
    ctx.beginPath(); ctx.moveTo(-4, -5); ctx.lineTo(4, -5); ctx.stroke();
    // wrench mark painted on the floor
    ctx.strokeStyle = "#c9cf52"; ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(-10, -4.6); ctx.lineTo(-7.2, -1.8); ctx.stroke();
    ctx.beginPath(); ctx.arc(-10.8, -5.4, 1.6, 0.9, 5.2); ctx.stroke();
    ctx.beginPath(); ctx.arc(-6.4, -1, 1.6, 4.0, 2.2); ctx.stroke();
    ctx.lineWidth = 1;
    // overhead hoist beam (tall) over the pit
    ctx.fillStyle = C.sh(C.steel, -50);
    ctx.fillRect(-6, -8, 2, 5); ctx.fillRect(4, -8, 2, 5);
    ctx.fillStyle = "#d0a43c"; ctx.fillRect(-7, -10.5, 14, 2.5);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-7, -10.5, 14, 2.5);
    ctx.beginPath(); ctx.moveTo(0, -8); ctx.lineTo(0, -5.2); ctx.stroke();
    ctx.fillStyle = C.dk; ctx.fillRect(-0.8, -5.2, 1.6, 1.2);
    // tyre stack
    function tyre(x, y, r) {
      ctx.fillStyle = C.trk;
      ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = C.dk; ctx.stroke();
      ctx.fillStyle = "#3d4145";
      ctx.beginPath(); ctx.arc(x, y, r * 0.45, 0, Math.PI * 2); ctx.fill();
    }
    tyre(12, 5.5, 2.6); tyre(12, 0.8, 2.2);
    // faction patch
    ctx.fillStyle = C.main; ctx.fillRect(-13, -8, 3, 2.5);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-13, -8, 3, 2.5);
  }
};

BLD_DETAIL["derrick"] = {
  draw: function (ctx, C, t) {
    ctx.lineWidth = 1;
    // dark oil pool
    ctx.fillStyle = "#1d2023";
    ctx.beginPath(); ctx.ellipse(3, 7, 5, 2.2, 0, 0, Math.PI * 2); ctx.fill();
    // small tank
    ctx.fillStyle = "#8d9499";
    ctx.beginPath(); ctx.arc(7, -4, 3, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = C.dk; ctx.stroke();
    ctx.strokeStyle = C.sh("#8d9499", 40);
    ctx.beginPath(); ctx.arc(7, -4, 3, Math.PI * 0.9, Math.PI * 1.6); ctx.stroke();
    ctx.fillStyle = C.sh("#8d9499", -30);
    ctx.beginPath(); ctx.arc(7, -4, 1, 0, Math.PI * 2); ctx.fill();
    // lattice truss tower, X-braced (tall)
    var ax = -3, ay = -7;
    ctx.strokeStyle = C.steel;
    ctx.beginPath();
    ctx.moveTo(ax - 4, 3); ctx.lineTo(ax, ay); ctx.lineTo(ax + 4, 3);
    ctx.moveTo(ax - 3, 0); ctx.lineTo(ax + 3, 0);
    ctx.moveTo(ax - 2, -3); ctx.lineTo(ax + 2, -3);
    ctx.moveTo(ax - 3, 0); ctx.lineTo(ax + 2, -3);
    ctx.moveTo(ax + 3, 0); ctx.lineTo(ax - 2, -3);
    ctx.stroke();
    ctx.strokeStyle = C.dk;
    ctx.beginPath(); ctx.moveTo(ax - 4, 3); ctx.lineTo(ax + 4, 3); ctx.stroke();
    // walking beam rocking on the apex
    var rock = Math.sin(t * 2.2) * 0.28;
    ctx.save();
    ctx.translate(ax, ay); ctx.rotate(rock);
    ctx.fillStyle = "#b0483a";
    ctx.fillRect(-5, -1, 10, 2);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-5, -1, 10, 2);
    ctx.fillStyle = "#b0483a";
    ctx.beginPath(); ctx.arc(-5, 0, 1.8, Math.PI * 0.5, Math.PI * 1.5); ctx.fill();
    ctx.fillStyle = C.dk; ctx.fillRect(4, -1.6, 2, 3.2);
    ctx.restore();
    // pump rod down to the wellhead
    var hx = ax - Math.cos(rock) * 6, hy = ay - Math.sin(rock) * 6;
    ctx.strokeStyle = C.dk;
    ctx.beginPath(); ctx.moveTo(hx, hy); ctx.lineTo(hx, 4); ctx.stroke();
    ctx.fillStyle = "#3a3e42"; ctx.fillRect(hx - 1, 4, 2, 1.5);
    // faction patch
    ctx.fillStyle = C.main; ctx.fillRect(-10, 6, 3, 2);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-10, 6, 3, 2);
  }
};

BLD_DETAIL["silo"] = {
  draw: function (ctx, C, t) {
    ctx.lineWidth = 1;
    function tank(x, y) {
      ctx.fillStyle = "#98a0a6";
      ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = C.dk; ctx.stroke();
      ctx.strokeStyle = C.sh("#98a0a6", 45);
      ctx.beginPath(); ctx.arc(x, y, 5, Math.PI * 0.85, Math.PI * 1.55); ctx.stroke();
      ctx.strokeStyle = C.sh("#98a0a6", -40);
      ctx.beginPath(); ctx.arc(x, y, 5, -0.3, 0.55 * Math.PI); ctx.stroke();
      ctx.beginPath(); ctx.arc(x, y, 3.3, 0, Math.PI * 2); ctx.stroke();
      // top hatch
      ctx.fillStyle = C.sh("#98a0a6", -20);
      ctx.beginPath(); ctx.arc(x + 1, y - 1, 1.5, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = C.dk; ctx.stroke();
      // ladder rails + rungs
      ctx.strokeStyle = C.sh("#98a0a6", -45);
      ctx.beginPath();
      ctx.moveTo(x - 0.9, y + 1.8); ctx.lineTo(x - 1.7, y + 4.6);
      ctx.moveTo(x + 0.5, y + 2); ctx.lineTo(x + 0.9, y + 4.8);
      ctx.moveTo(x - 1.3, y + 3); ctx.lineTo(x + 0.7, y + 3.1);
      ctx.moveTo(x - 1.5, y + 4); ctx.lineTo(x + 0.8, y + 4.1);
      ctx.stroke();
    }
    tank(-5.5, -2); tank(5.5, -2);
    // connecting pipe
    ctx.strokeStyle = C.steel; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-2, -2); ctx.lineTo(2, -2); ctx.stroke();
    ctx.lineWidth = 1;
    // fill-level gauge bar
    ctx.fillStyle = "#2e3236"; ctx.fillRect(-6, 6, 12, 3);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-6, 6, 12, 3);
    var lvl = 0.55 + 0.1 * Math.sin(t * 0.5);
    ctx.fillStyle = "#d8b44a"; ctx.fillRect(-5.4, 6.6, 10.8 * lvl, 1.8);
    // faction patch
    ctx.fillStyle = C.main; ctx.fillRect(-10, -9, 3, 2);
    ctx.strokeStyle = C.dk; ctx.strokeRect(-10, -9, 3, 2);
  }
};

